window.kbPageData["views/entry/k-8ad204b416d318ef"] = {"key":"entry/k-8ad204b416d318ef","state":{"route":"entry/k-8ad204b416d318ef"},"node":{"id":"k-8ad204b416d318ef","mode":"k","title":"民营经济发展的基本方针政策","type":"制度与规则","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":["民营经济"],"qs":["政治理论必刷100题#43"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"专题":["market"],"主类":["制度与规则"],"出处性质":["专项题干","机构注释"],"学科":["政治理论","经济"],"来源主题":["产业、科技与对外开放"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"党和国家对民营经济发展的基本方针政策，已经纳入中国特色社会主义制度体系，将一以贯之坚持和落实。","review":{"definition":"党和国家对民营经济发展的基本方针政策，已经纳入中国特色社会主义制度体系，将一以贯之坚持和落实。","explanation":"2025年2月17日民营企业座谈会上的讲话明确了这些基本方针政策的制度定位和持续性。D项的“不能变，也不会变”指的正是这些基本方针政策，符合讲话表述。","references":[],"evidence":"党和国家对民营经济发展的基本方针政策，已经纳入中国特色社会主义制度体系","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"213cbd4fab59c3ce","label":"民营经济","topic":"产业、科技与对外开放","category":"非时政","text":"2.民营经济\n民营经济是我国经济制度的内在要素。民营经济是社会主义市场经济发展的重要成果，\n是推动社会主义市场经济发展的重要力量，是推进供给侧结构性改革、推动高质量发展、建\n设现代化经济体系的重要主体，也是我们党长期执政、团结带领全国人民实现“两个一百年”\n奋斗目标和中华民族伟大复兴中国梦的重要力量。\n习近平总书记在民营企业座谈会上的讲话中指出，我国民营经济已经成为推动我国发展\n不可或缺的力量，成为创业就业的主要领域、技术创新的重要主体、国家税收的重要来源，\n为我国社会主义市场经济发展、政府职能转变、农村富余劳动力转移、国际市场开拓等发挥\n了重要作用。\n——2018 年 11 月习近平在民营企业座谈会上的讲话","source":{"doc":"6cbfb01fe723bba64b75","first":29,"last":30,"page":29,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#43":{"paper":"政治理论必刷100题","n":43,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",13],"asrc":["国省考政治理论必刷100题.pdf",58],"card":"6365c94ac9ad29de0b4faff0","links":[{"id":"k-8ad204b416d318ef","role":"直接考查","why":"考查民营经济基本方针政策的制度定位和持续性。"}]}},"terms":{},"references":{},"topics":[{"slug":"market","title":"统一大市场与公平竞争"}],"units":{"k-8ad204b416d318ef":[["政治理论必刷100题#43"]]}};
